def split_words(txt):
    import re
    if re.search(r'\s', txt):
        return txt.split()
    elif re.search(r',', txt):
        return txt.split(',')
    else:
        count = 0
        for char in txt:
            if 'a' <= char <= 'z':
                if (ord(char) - ord('a')) % 2 == 1:
                    count += 1
        return count
